function printDialog(){
  if(!active||!active.rows.length){toast('表格中还没有可打印的数据。');return;}
  modal('打印表格',`<label class="modal-field"><span>打印内容</span><select id="print-scope"><option value="all">当前完整总表（${active.rows.length} 条）</option><option value="filtered">筛选结果（${dataset().exported.length} 条）</option><option value="groups">选中分组，每组单独起页</option></select></label><div class="preset-choices"><label class="modal-field"><span>纸张</span><select id="print-paper"><option>A4</option><option>A3</option></select></label><label class="modal-field"><span>方向</span><select id="print-orientation"><option value="landscape">横向</option><option value="portrait">纵向</option></select></label></div><label class="modal-field"><span>宽表排版</span><select id="print-layout"><option value="segments">分段打印，重复前 3 列</option><option value="fit">全部列缩放至纸张宽度</option></select></label><label class="modal-field"><span>打印字段</span><select id="print-columns"><option value="all">全部字段</option><option value="selected">使用已选导出字段</option></select></label><div class="modal-help">自动重复表头。可在打印窗口选择打印机，或保存为 PDF。</div>`,'预览并打印',()=>{
    const scope=$('print-scope').value,data=dataset(),columns=$('print-columns').value==='all'?active.columns:active.columns.filter(c=>exportColumns.has(c.id));
    const groups=scope==='all'?[{name:active.name,rows:active.rows}]:scope==='filtered'?[{name:active.name+' · 筛选结果',rows:data.exported}]:data.chosen.map(g=>({...g,name:g.name+' · '+active.name}));
    if(!columns.length||!groups.some(g=>g.rows.length))throw new Error('没有可打印的数据。');
    const paper=$('print-paper').value,orientation=$('print-orientation').value,layout=$('print-layout').value;const maxCols=paper==='A3'?(orientation==='landscape'?15:10):(orientation==='landscape'?10:7);
    const segments=[];if(layout==='fit'||columns.length<=maxCols)segments.push(columns);else{const repeated=columns.slice(0,3);for(let i=3;i<columns.length;i+=maxCols-3)segments.push([...repeated,...columns.slice(i,i+maxCols-3)]);}
    recalculateAll(active);
    const format=c=>{if(c?.t==='n'){const decimals=c.z?.match(/\.([0#]+)/)?.[1]?.length;return c.v.toLocaleString('zh-CN',{maximumFractionDigits:decimals??8,minimumFractionDigits:decimals??0});}return display(c);};
    const content=groups.map(group=>segments.map((segment,n)=>`<section><table><colgroup>${segment.map(c=>`<col style="width:${Math.min(c.width||18,35)}em">`).join('')}</colgroup><thead><tr class="title"><td colspan="${segment.length}"><h1>${h(group.name)}</h1><p>记录数：${group.rows.length}${segments.length>1?'　字段分段：'+(n+1)+' / '+segments.length:''}</p></td></tr><tr>${segment.map(c=>`<th>${h(c.name)}</th>`).join('')}</tr></thead><tbody>${group.rows.map(row=>`<tr>${segment.map(c=>{const i=active.columns.indexOf(c);return `<td class="${c.type==='number'?'number':''}">${h(format(row.cells[i]))}</td>`;}).join('')}</tr>`).join('')}</tbody></table></section>`).join('')).join('');
    const text=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${h(active.name)}</title><style>@page{size:${paper} ${orientation};margin:10mm}*{box-sizing:border-box}body{margin:0;font-family:"Microsoft YaHei",-apple-system,sans-serif;color:#263549}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:${layout==='fit'&&columns.length>15?'7.5':'9'}pt}thead{display:table-header-group}th,td{border:.5pt solid #bbc7d4;padding:5pt 4pt;word-break:break-word;white-space:pre-wrap;line-height:1.5}th{background:#254665;color:white;font-weight:bold;-webkit-print-color-adjust:exact;print-color-adjust:exact}.title td{border:0;padding:0 0 10pt}.title h1{font-size:18pt;color:#173a5e;margin:0 0 5pt;font-weight:650}.title p{font-size:10pt;color:#65758b;margin:0}tr{break-inside:avoid}section{break-before:page}section:first-child{break-before:auto}.number{text-align:right;font-variant-numeric:tabular-nums}</style><body>${content}</body></html>`;
    let frame=$('print-frame');if(frame)frame.remove();frame=document.createElement('iframe');frame.id='print-frame';frame.title='打印预览';frame.className='print-frame';frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};document.body.append(frame);frame.srcdoc=text;closeModal(false);
  });
}
$('print-open').onclick=printDialog;
